ALTER POLICY tender_storage_add ON storage.objects WITH CHECK(bucket_id='tender-documents' AND (storage.foldername(objects.name))[1]=public.my_company()::text AND lower(storage.extension(objects.name)) IN ('pdf','docx','xlsx') AND EXISTS(SELECT 1 FROM public.tenders t WHERE t.company_id=public.my_company() AND t.id::text=(storage.foldername(objects.name))[2] AND t.status='uploading'));
ALTER POLICY tender_storage_cleanup ON storage.objects USING(bucket_id='tender-documents' AND (storage.foldername(objects.name))[1]=public.my_company()::text AND EXISTS(SELECT 1 FROM public.tenders t WHERE t.company_id=public.my_company() AND t.id::text=(storage.foldername(objects.name))[2] AND t.status='uploading'));